"""Data Agent V6 P3 生产运营问题集。

问题按实际的 13 个权威 reader 组织，每族 8 个自然语言变体，共 104 题。原 V6 方案的
11 个业务问题族会把任务/任务链、数据源/组件、草稿/合并/冲突合并统计；这里按 reader
拆开，是为了让“正确 family”成为可执行断言，而不是人工印象分。
"""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class OpsQuestion:
    id: str
    family: str
    group: str
    question: str

    @property
    def tool(self) -> str:
        return "get_landing" if self.family == "landing" else "get_ops_record"


def _family(
    family: str,
    group: str,
    questions: tuple[str, ...],
) -> list[OpsQuestion]:
    assert len(questions) == 8, f"{family} 必须正好有 8 题"
    return [
        OpsQuestion(
            id=f"{family}-{index:02d}",
            family=family,
            group=group,
            question=question,
        )
        for index, question in enumerate(questions, start=1)
    ]


